using System;using System.IO;
class GoldLootFixtures {
 internal static int Run(string dir){Directory.CreateDirectory(dir);byte[] keys=new byte[334];for(int i=0;i<334;i++)keys[i]=(byte)i;
  foreach(int ix in new int[]{4,11,13})foreach(int n in new int[]{1,2,4}){int block=ix==11?8:16;byte[] b=new byte[block*n];for(int i=0;i<b.Length;i++)b[i]=(byte)i;byte[] encrypted=Offline70GoldCipher.Crypt(b,keys,ix,true),back=Offline70GoldCipher.Crypt(encrypted,keys,ix,false);File.WriteAllBytes(Path.Combine(dir,"cipher"+ix+"-"+n+".bin"),encrypted);for(int i=0;i<b.Length;i++)if(back[i]!=b[i])throw new InvalidDataException("Gold cipher roundtrip "+ix);}
  Offline70Role role=new Offline70Role{Id=1,Name="yoyo",Job=0,Level=1};string run="1234567890abcdef1234567890abcdef",store=Path.Combine(dir,"gold-fixture.xml");if(File.Exists(store))throw new InvalidDataException("Do not overwrite receipt fixture");bool duplicate;
  foreach(ushort uid in new ushort[]{100,101,102,103}){Offline70GoldDrop drop=new Offline70GoldDrop{Slot=(ushort)(2000+uid-100),Amount=18,Receipt=run+"-"+(2000+uid-100)};File.WriteAllBytes(Path.Combine(dir,"death"+uid+".plain.bin"),Offline70GoldLoot.DeathBody(uid,drop));File.WriteAllBytes(Path.Combine(dir,"death"+uid+".packet.bin"),Offline70GoldLoot.DeathReply(uid,drop,role,keys));File.WriteAllBytes(Path.Combine(dir,"pickup"+drop.Slot+".plain.bin"),Offline70GoldLoot.PickupBody(drop.Slot,18));File.WriteAllBytes(Path.Combine(dir,"pickup"+drop.Slot+".packet.bin"),Offline70GoldLoot.PickupReply(drop.Slot,18,keys));
   byte[] request=new byte[16];BitConverter.GetBytes(drop.Slot).CopyTo(request,0);BitConverter.GetBytes((ushort)200).CopyTo(request,4);BitConverter.GetBytes((ushort)210).CopyTo(request,6);BitConverter.GetBytes((ushort)200).CopyTo(request,10);BitConverter.GetBytes((ushort)210).CopyTo(request,12);byte[] encrypted=Offline70GoldCipher.Crypt(request,keys,4,true);File.WriteAllBytes(Path.Combine(dir,"request"+drop.Slot+".bin"),encrypted);if(BitConverter.ToUInt16(Offline70GoldLoot.ParsePlain(encrypted,keys),0)!=drop.Slot)throw new InvalidDataException("Gold request parse");
   Offline70GoldState s=Offline70GoldLoot.Pickup(store,drop,100,out duplicate);if(duplicate||s.Earned!=(uid-99)*18)throw new InvalidDataException("Gold commit fixture");byte[] before=File.ReadAllBytes(store);s=Offline70GoldLoot.Pickup(store,drop,100,out duplicate);if(!duplicate||Convert.ToBase64String(before)!=Convert.ToBase64String(File.ReadAllBytes(store)))throw new InvalidDataException("Gold duplicate mutated balance");
  }
  File.WriteAllBytes(Path.Combine(dir,"ack46.packet.bin"),Offline70GoldLoot.Ack(keys));foreach(uint gold in new uint[]{0,100,118,172}){File.WriteAllBytes(Path.Combine(dir,"restore"+gold+".plain.bin"),Offline70QuestFinish.GoldRestoreBody(gold));File.WriteAllBytes(Path.Combine(dir,"restore"+gold+".packet.bin"),Offline70QuestFinish.GoldRestoreReply(keys,gold));}
  if(Offline70GoldLoot.Roll(985,-15,false)!=15||Offline70GoldLoot.Roll(986,15,false)!=0||Offline70GoldLoot.Roll(9999,15,true)!=20)throw new InvalidDataException("PVF gold boundaries");
  byte[] bad=new byte[16];BitConverter.GetBytes((ushort)1999).CopyTo(bad,0);bool rejected=false;try{Offline70GoldLoot.ParsePlain(Offline70GoldCipher.Crypt(bad,keys,4,true),keys);}catch(InvalidDataException){rejected=true;}if(!rejected)throw new InvalidDataException("Invalid gold scene accepted");
  Console.WriteLine("PASS native cipher fixtures, four atomic gold commits, four durable duplicate rejections, variable balance and malformed request rejection");return 0;
 }
